From 91f329e0c434489c407cee77ff912d6b559c0eac Mon Sep 17 00:00:00 2001
From: jongleberry <jonathanrichardong@gmail.com>
Date: Thu, 15 Oct 2026 00:16:43 -0700
Subject: [PATCH 2/3] bench(extract): cover no-import fact construction with
 call demand

---
 .../benches/core_analysis/extract.rs          | 26 +++++++++++++++++++
 1 file changed, 26 insertions(+)

diff --git a/crates/no-mistakes/benches/core_analysis/extract.rs b/crates/no-mistakes/benches/core_analysis/extract.rs
index 6db44e60d..d94b7026d 100644
--- a/crates/no-mistakes/benches/core_analysis/extract.rs
+++ b/crates/no-mistakes/benches/core_analysis/extract.rs
@@ -56,4 +56,30 @@ pub(super) fn bench_extract_import_facts(c: &mut Criterion) {
         },
     );
     group.finish();
+    bench_no_import_fact_construction(c);
+}
+
+// Keep function-call facts enabled for both demands: the no-values arm is not
+// an imports-only extraction shortcut, and every iteration owns fresh facts.
+fn bench_no_import_fact_construction(c: &mut Criterion) {
+    use no_mistakes::codebase::ts_source::facts::{collect_ts_facts, TsFactPlan};
+    let file = std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR"))
+        .join("../../test-cases/codebase-analysis/import-facts/fixture/shared-destructuring.mts");
+    let mut group = c.benchmark_group("extract/no_import_fact_construction");
+    for values in [false, true] {
+        let plan = TsFactPlan {
+            imports: true,
+            function_calls: true,
+            value_flow: values,
+            ..Default::default()
+        };
+        let facts = collect_ts_facts(std::slice::from_ref(&file), plan);
+        let fact = facts.get(&file).unwrap();
+        assert!(fact.parse_error.is_none() && fact.operational_error.is_none());
+        assert_eq!(fact.value_flow.bindings.len(), if values { 128 } else { 0 });
+        group.bench_with_input(BenchmarkId::from_parameter(values), &plan, |b, plan| {
+            b.iter(|| black_box(collect_ts_facts(std::slice::from_ref(&file), *plan)));
+        });
+    }
+    group.finish();
 }
-- 
