From 496ee2d59ec25d3a58fecdf75f29a98c0e9d2615 Mon Sep 17 00:00:00 2001
From: jongleberry <jonathanrichardong@gmail.com>
Date: Thu, 15 Oct 2026 00:46:44 -0700
Subject: [PATCH 3/3] perf(extract): reuse lexical lookup for retained symbol
 references

---
 .../extract/tests/import_shadow_work.rs       | 38 ++++++++++++++++---
 .../dependencies/extract_collector.rs         |  4 +-
 .../dependencies/extract_visit_helpers.rs     | 24 +++++++-----
 3 files changed, 49 insertions(+), 17 deletions(-)

diff --git a/crates/no-mistakes/src/codebase/dependencies/extract/tests/import_shadow_work.rs b/crates/no-mistakes/src/codebase/dependencies/extract/tests/import_shadow_work.rs
index e4465fa27..b2058c4fb 100644
--- a/crates/no-mistakes/src/codebase/dependencies/extract/tests/import_shadow_work.rs
+++ b/crates/no-mistakes/src/codebase/dependencies/extract/tests/import_shadow_work.rs
@@ -1,7 +1,7 @@
 use super::*;

 #[test]
-fn shared_destructuring_skips_nonimport_shadow_scope_scans() {
+fn shared_destructuring_reuses_one_reference_scope_lookup() {
     let path = std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR"))
         .join("../../test-cases/codebase-analysis/import-facts/fixture/shared-destructuring.mts");
     let source = std::fs::read_to_string(path).unwrap();
@@ -16,12 +16,38 @@ fn shared_destructuring_skips_nonimport_shadow_scope_scans() {
         predeclare_program_value_bindings(&mut collector, &parsed.program);
         collector.visit_program(&parsed.program);
         assert!(!collector.symbol_references.is_empty());
-        // Function-call collection stays enabled; only impossible import shadows skip lookup.
-        assert_eq!(collector.import_shadow_scope_scans.get(), 0);
+        // An unrelated import must not force a second lexical scan for each
+        // retained reference; both demands still collect function-call facts.
+        for has_import in [false, true] {
+            if has_import {
+                collector.imported_bindings.insert("unrelated".to_owned());
+            }
+            collector.lexical_scope_queries.set(0);
+            let before = collector.symbol_references.len();
+            for _ in 0..128 {
+                collector.push_value_symbol_reference("target.member".to_owned());
+            }
+            assert_eq!(collector.symbol_references.len() - before, 128);
+            assert!(collector.symbol_references[before..].iter().all(|reference| {
+                reference.callee_binding_scope == Some(0)
+            }));
+            assert_eq!(collector.lexical_scope_queries.get(), 128, "import={has_import}");
+        }
         collector.imported_bindings.insert("target".to_owned());
-        assert!(collector.callee_shadows_import("target.member"));
+        let before = collector.symbol_references.len();
+        collector.lexical_scope_queries.set(0);
+        collector.push_value_symbol_reference("target.member".to_owned());
+        assert_eq!(collector.symbol_references.len(), before);
+        assert_eq!(collector.lexical_scope_queries.get(), 1);
+        collector.imported_bindings.clear();
         collector.predeclared_imported_bindings.insert("pending".to_owned());
-        assert!(!collector.callee_shadows_import("pending.member"));
-        assert_eq!(collector.import_shadow_scope_scans.get(), 2);
+        collector.push_value_symbol_reference("pending.member".to_owned());
+        assert_eq!(collector.symbol_references.last().unwrap().callee_binding_scope, None);
+        assert_eq!(collector.lexical_scope_queries.get(), 2);
+        collector.local_stack[0].insert("pending".to_owned());
+        let before = collector.symbol_references.len();
+        collector.push_value_symbol_reference("pending.member".to_owned());
+        assert_eq!(collector.symbol_references.len(), before);
+        assert_eq!(collector.lexical_scope_queries.get(), 3);
     }
 }
diff --git a/crates/no-mistakes/src/codebase/dependencies/extract_collector.rs b/crates/no-mistakes/src/codebase/dependencies/extract_collector.rs
index 2e5ec66f9..8b2af5375 100644
--- a/crates/no-mistakes/src/codebase/dependencies/extract_collector.rs
+++ b/crates/no-mistakes/src/codebase/dependencies/extract_collector.rs
@@ -18,8 +18,8 @@ struct AggregateAliasCandidate {
 #[derive(Default)]
 struct ImportCollector {
     bare_callable_callee: Option<u32>,
-    #[cfg(test)]
-    import_shadow_scope_scans: std::cell::Cell<usize>,
+    #[cfg(feature = "test-instrumentation")]
+    lexical_scope_queries: std::cell::Cell<usize>,
     /// 0-based byte offsets of each line start. Empty when line numbers are
     /// unused so the collector does not retain a full source copy.
     line_starts: Vec<u32>,
diff --git a/crates/no-mistakes/src/codebase/dependencies/extract_visit_helpers.rs b/crates/no-mistakes/src/codebase/dependencies/extract_visit_helpers.rs
index 6da5f2107..0428a63a1 100644
--- a/crates/no-mistakes/src/codebase/dependencies/extract_visit_helpers.rs
+++ b/crates/no-mistakes/src/codebase/dependencies/extract_visit_helpers.rs
@@ -30,10 +30,18 @@ impl ImportCollector {

     fn push_value_symbol_reference(&mut self, name: String) {
         let caller = self.current_function();
-        if self.callee_shadows_import(&name) {
+        // Share the lexical lookup between shadow filtering and the retained scope.
+        let binding = name.split_once('.').map_or(name.as_str(), |(binding, _)| binding);
+        #[cfg(feature = "test-instrumentation")]
+        self.lexical_scope_queries.set(self.lexical_scope_queries.get() + 1);
+        let depth = self.local_stack.iter().rposition(|scope| scope.contains(binding));
+        if depth.is_some()
+            && (self.imported_bindings.contains(binding)
+                || self.predeclared_imported_bindings.contains(binding))
+        {
             return;
         }
-        let callee_binding_scope = self.callee_binding_scope(&name);
+        let callee_binding_scope = depth.map(|depth| self.lexical_scope_ids[depth]);
         self.symbol_references.push(FunctionCall {
             caller,
             caller_id: self.current_function_id(),
@@ -125,6 +133,8 @@ impl ImportCollector {
     }

     fn local_binding_shadows(&self, name: &str) -> bool {
+        #[cfg(feature = "test-instrumentation")]
+        self.lexical_scope_queries.set(self.lexical_scope_queries.get() + 1);
         self.local_stack
             .iter()
             .rev()
@@ -139,6 +149,8 @@ impl ImportCollector {
     }

     fn callee_binding_scope(&self, callee: &str) -> Option<usize> {
+        #[cfg(feature = "test-instrumentation")]
+        self.lexical_scope_queries.set(self.lexical_scope_queries.get() + 1);
         let binding = callee
             .split_once('.')
             .map_or(callee, |(binding, _)| binding);
@@ -194,12 +206,6 @@ impl ImportCollector {
         let binding = callee
             .split_once('.')
             .map_or(callee, |(binding, _)| binding);
-        if self.imported_bindings.is_empty() && self.predeclared_imported_bindings.is_empty() {
-            return false;
-        }
-        #[cfg(test)]
-        self.import_shadow_scope_scans
-            .set(self.import_shadow_scope_scans.get() + 1);
         self.local_binding_shadows(binding)
             && (self.imported_bindings.contains(binding)
                 || self.predeclared_imported_bindings.contains(binding))
@@ -208,6 +214,6 @@ impl ImportCollector {

 include!("extract_callable_scope_helper.rs");

-#[cfg(test)]
+#[cfg(all(test, feature = "test-instrumentation"))]
 #[path = "extract/tests/import_shadow_work.rs"]
 mod import_shadow_work;
